let ekData=null,ekAt=0,ekLoading=false,ekOpen=null;
async function loadEk(force=false){if(ekLoading||(!force&&ekData&&Date.now()-ekAt<30000))return;ekLoading=true;try{ekData=await api('eval-keys');ekAt=Date.now();}catch(e){toast(e.message)}finally{ekLoading=false;if(tab==='evalkeys')draw();}}
function ekStyle(){if(document.querySelector('#ekStyle'))return;const st=document.createElement('style');st.id='ekStyle';st.textContent=`
.ek-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(360px,1fr));gap:12px}.ek-card{padding:14px 16px;border:1px solid var(--lab-line);border-radius:12px;background:var(--lab-surface);min-width:0}.ek-card.none{border-style:dashed}.ek-card.is-down{border-color:var(--lab-red)}
.ek-card header{display:flex;gap:8px;align-items:center;margin-bottom:6px}.ek-card header h3{margin:0;font-size:15px;flex:1}.ek-card header small{color:var(--lab-dim);font-size:11px}
.ek-card .ek-meta{font-size:11px;color:var(--lab-dim);margin-bottom:8px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ek-form{display:grid;gap:8px;margin-top:10px}.ek-form label{display:grid;gap:4px;font-size:11px;color:var(--lab-dim)}.ek-form input{width:100%;padding:8px;border-radius:8px;border:1px solid var(--lab-line);background:var(--lab-bg);color:var(--lab-text);font:inherit;font-size:12px}
.ek-form .row{gap:10px}.ek-why{font-size:12px;color:var(--lab-dim);line-height:1.7}.ek-why b{color:var(--lab-text)}`;document.head.append(st);}
function ekCard(v){const k=v.key,results=new Map((k?.last_check_models||[]).map(r=>[r.model,r]));
 const models=k?upModelOrder(k.models,results).map(m=>{const r=results.get(m),st=!r?'idle':r.ok?'ok':'bad';return `<div class="up-m ${st}" title="${esc(r?.error||'')}"><i></i><b>${esc(m)}</b><span>${!r?'未检测':r.ok?r.ms+' ms':(r.status?'HTTP '+r.status:'失败')}</span>${r&&!r.ok?`<small>${esc(r.error||'')}</small>`:''}</div>`}).join(''):'';
 const check=k?.last_check_at?`${upAgo(k.last_check_at)} · ${k.last_check_ok?'<span class="cmp-ok">全部接通</span>':'<span class="cmp-bad">有型号不通</span>'}${k.last_check_model?' · '+esc(k.last_check_model):''}`:'还没检测';
 const state=!k?['','没有 Key']:k.last_check_at&&!k.last_check_ok?['bad','有型号不通']:k.last_check_ok?['ok','可用']:['','未检测'];
 const form=(!k||ekOpen===v.id)?`<form class="ek-form" data-ek-form="${esc(v.id)}"><label>官方 API Key（只在提交时出现一次）<input name="api_key" type="password" autocomplete="off" required placeholder="sk-…"></label><label>型号 ID（逗号分隔；保存时会先向官方要一次列表，拿不到就用这里的）<input name="model_ids" value="${esc(v.suggested.join(', '))}"></label><div class="row"><button class="button" type="submit">${k?'换成这把 Key':'保存并检测'}</button>${k?`<button class="link" type="button" data-ek-cancel>取消</button>`:''}<span class="note">接口地址 ${esc(v.base_url)}</span></div></form>`:'';
 return `<article class="ek-card ${!k?'none':''} ${state[0]==='bad'?'is-down':''}"><header><h3>${esc(v.name)}</h3><small>${esc(v.family==='glm'?'GLM 系列':'DeepSeek 系列')} · ${esc(v.region)}</small><span class="up-tag ${state[0]}">● ${state[1]}</span></header>${k?`<div class="ek-meta">最近检测 ${check} · 指纹 ${esc(k.credential_fingerprint)} · 登记 ${upAgo(k.created_at)}${v.retired?` · 已换过 ${v.retired} 次`:''}</div><div class="up-models">${models||'<span class="note">没有型号</span>'}</div>${ekOpen===v.id?'':`<div class="row" style="margin-top:10px"><button class="button" data-up-check="${esc(k.id)}">检测全部型号</button><button class="link" data-ek-replace="${esc(v.id)}">更换 Key</button><button class="link muted" data-ek-disable="${esc(k.id)}">停用</button></div>`}`:`<p class="note">在 <a href="${esc(v.console)}" target="_blank" rel="noopener">${esc(new URL(v.console).host)}</a> 开通后把 Key 贴进来。</p>`}${form}</article>`;}
function evalKeysView(){overviewStyle();upStyle();ekStyle();const d=ekData;if(!d||Date.now()-ekAt>30000)void loadEk();if(!d)return '<section class="panel">正在读取评测 Key…</section>';
 const why=`<details class="ov-card"><summary>这些 Key 用在哪里，为什么和采购 Key 分开</summary><div class="ek-why"><b>用途：</b>功能对比（官方实测结果当基准，看我们的 API 是否一样）、Agent 检测里的“官方也能跑吗”对照列、Agent 两条路对比里的官方那一路、第三方评审模型。<br><b>隔离：</b>它们登记为“官方参照”型号，员工路由只在 KerAPI 的采购 Key 里选，代码上碰不到这里。<br><b>费用：</b>每次检测每个型号 1 个 Token；功能对比整轮约 ¥3–8，主要花在长上下文那几格。</div></details>`;
 const other=d.other.length?`<section class="ov-card"><h3>其他官方 Key <small>按旧方式登记的</small></h3>${d.other.map(k=>`<div class="note">${esc(k.vendor_name)} · ${esc(k.label)} · ${esc(k.base_url)} <button class="link muted" data-ek-disable="${esc(k.id)}">停用</button></div>`).join('')}</section>`:'';
 return `<section class="ov"><div class="ek-grid">${d.vendors.map(ekCard).join('')}</div>${other}${why}</section>`;}
document.addEventListener('click',async event=>{
 const rep=event.target.closest('[data-ek-replace]');if(rep){ekOpen=rep.dataset.ekReplace;draw();return;}
 if(event.target.closest('[data-ek-cancel]')){ekOpen=null;draw();return;}
 const dis=event.target.closest('[data-ek-disable]');if(dis){if(!confirm('停用这把官方评测 Key？对比评测和功能对比会暂时没有官方对照。'))return;try{await api('eval-keys/'+dis.dataset.ekDisable+'/disable',{method:'POST',body:'{}'});toast('已停用');await loadEk(true);cmpData=null;}catch(e){toast(e.message)}return;}
 const chk=event.target.closest('[data-up-check]');if(chk&&tab==='evalkeys'){event.stopImmediatePropagation();chk.disabled=true;chk.textContent='检测中…';try{const r=await api('credentials/'+chk.dataset.upCheck+'/check',{method:'POST',body:'{}'});toast(r.ok?`${r.passed} 个型号全部接通`:`${r.passed} 接通；${r.error}`);}catch(e){toast(e.message)}await loadEk(true);return;}
},true);
